/**
 * Balance catalog Part 2 providing high-difficulty questions for underrepresented categories:
 * - Animals & Zoology: 30 Very Hard, 15 Challenge
 * - Sports & Athletics: 20 Very Hard, 10 Challenge
 * - Art & Music: 20 Very Hard, 10 Challenge
 * - Geography & Exploration: 20 Very Hard, 10 Challenge
 * - Technology & Computing: 20 Very Hard, 10 Challenge
 */
object HighDifficultyBalancePart2 {

  fun getQuestions(language: AppLanguage): List<Question> {
    val list = mutableListOf<Question>()
    buildAnimalQuestions(list, language)
    buildSportsQuestions(list, language)
    buildArtMusicQuestions(list, language)
    buildGeographyQuestions(list, language)
    buildTechnologyQuestions(list, language)
    return list
  }

