      Part2Item("ch_tech_cray_1_supercomputer_vector_year", "In what year was the iconic Seymour Cray-designed CRAY-1 vector supercomputer installed at Los Alamos?", "في أي عام ميلادي تم تركيب أول حاسوب فائق متجهي CRAY-1 في مختبر لوس ألاموس الوطني؟", listOf("1976", "١٩٧٦"), 98, "technology", AnswerType.YEAR, 1976.0),
      Part2Item("ch_tech_quantum_shor_algorithm_factoring_year", "In what year did Peter Shor formulate his polynomial-time quantum algorithm for integer factorization?", "في أي عام ميلادي صاغ بيتر شور خوارزميته الكمومية الشهيرة لتحليل الأعداد الأولية بزمن متعدد الحدود؟", listOf("1994", "١٩٩٤"), 99, "technology", AnswerType.YEAR, 1994.0),
      Part2Item("ch_tech_grover_quantum_search_algorithm_year", "In what year did Lov Grover publish his fast quantum database search algorithm offering quadratic speedup?", "في أي عام ميلادي نشر لوف غروفر خوارزميته الكمومية لتسريع البحث في قواعد البيانات غير المرتبة؟", listOf("1996", "١٩٩٦"), 98, "technology", AnswerType.YEAR, 1996.0),
      Part2Item("ch_tech_page_rank_algorithm_patented_year", "In what year was Larry Page and Sergey Brin's PageRank web search algorithm patented at Stanford (1998)?", "في أي عام ميلادي سُجلت براءة اختراع خوارزمية بيج رانك (PageRank) في جامعة ستانفورد؟", listOf("1998", "١٩٩٨"), 96, "technology", AnswerType.YEAR, 1998.0),
      Part2Item("ch_tech_first_transatlantic_wireless_marconi_year", "In what year did Guglielmo Marconi transmit the first transatlantic radio signal (Morse letter S) in 1901?", "في أي عام ميلادي نجح غولييلمو ماركوني في إرسال أول إشارة راديو لاسلكية عبر المحيط الأطلسي؟", listOf("1901", "١٩٠١"), 95, "technology", AnswerType.YEAR, 1901.0),
      Part2Item("ch_tech_first_optical_fiber_low_loss_corning_year", "In what year did Corning Glass researchers invent low-loss optical fiber capable of transmitting telecommunications (1970)?", "في أي عام ميلادي ابتكر باحثو شركة كورنينغ أول ألياف زجاجية بصرية منخفضة الفقد لنقل الاتصالات؟", listOf("1970", "١٩٧٠"), 97, "technology", AnswerType.YEAR, 1970.0)
    )
    addBatch(list, items, lang)
  }

  private fun addBatch(list: MutableList<Question>, items: List<Part2Item>, lang: AppLanguage) {
    for (item in items) {
      val qText = when (lang) {
        AppLanguage.ARABIC -> item.arabicQ
        else -> item.englishQ
      }
      val answers = when (lang) {
        AppLanguage.ARABIC -> item.answers
        else -> item.answers.filterNot { ans -> ans.any { it in '\u0600'..'\u06FF' } }
      }
      val tier = if (item.score >= 95) 6 else 5
      val prefix = if (tier == 6) "bal_c_" else "bal_vh_"
      list.add(
        Question(
          id = "${prefix}${item.concept}_${lang.code}",
          language = lang.code,
          category = item.category,
          difficulty = tier,
          question = qText,
          answerType = item.type,
          acceptedAnswers = if (answers.isNotEmpty()) answers else item.answers,
          correctNumericValue = item.numericVal,
          tolerance = if (item.numericVal != null) 0.01 else null,
          explanation = "Verified domain knowledge in ${item.category}.",
          difficultyScore = item.score,
          conceptId = item.concept
        )
      )
    }
  }

  data class Part2Item(
    val concept: String,
    val englishQ: String,
    val arabicQ: String,
    val answers: List<String>,
    val score: Int,
    val category: String,
    val type: AnswerType = AnswerType.TEXT,
    val numericVal: Double? = null
  )
}
